static __declspec(noinline) long _get_data(OggVorbis_File* vf)                   // 0x00C89C10 (static)
{
    errno = 0;
    if (vf->datasource) {
        char* buffer = ogg_sync_buffer(&vf->oy, CHUNKSIZE);
