    /* verify result */
    if (vf->pcm_offset > pos || pos > ov_pcm_total(vf, -1)) {
        result = OV_EFAULT;
        goto seek_error;
    }
    vf->bittrack = 0.f;
    vf->samptrack = 0.f;
    return (0);

seek_error:
    /* dump machine so we're in a known state */
    vf->pcm_offset = -1;
    _decode_clear(vf);
    return (int)result;
