        int ret = _open_seekable2(vf);
        if (ret) {
            vf->datasource = NULL;
            ov_clear(vf);
        }
        return (ret);
    } else
        vf->ready_state = STREAMSET;

    return 0;
}

int __fastcall ov_open_callbacks(void* f, OggVorbis_File* vf, char* initial, long ibytes)   // 0x00C8CAE0
{
    int ret = _ov_open1(f, vf, initial, ibytes);
