    vi.noisewindowlo = .15f; vi.noisewindowhi = .15f; vi.noisewindowlomin = 0; vi.noisewindowhimin = 0; vi.noisewindowfixed = 0;
    vi.tone_centerboost = 0.f; vi.tone_decay = 0.f;
