    if (!p.ath) return fail("ath alloc");
    for (i = 1; i < n; i++) if (p.ath[i] < p.ath[i - 1] - 1e-3f) return fail("ath monotone");
    if (p.ath[n / 2] < 79.f || p.ath[n / 2] > 103.f) return fail("ath level");
