    for (i = 0; i < 3; i++) for (j = 0; j < bins * 2; j++) bm.minmax_binstack[i * bins * 2 + j] = (j >= bins) ? 100 * i + 10 * (j - bins) : 0;
    bm.minmax_stackptr = 2; bm.minmax_acctotal = 1000;
    bm.minmax_limitstack[0] = 1; bm.minmax_limitstack[1] = 3; bm.minmax_limitstack[2] = 0;
    /* limit 2: the top frame swaps its limit-0 bytes for limit-2 bytes (+20), frame 1 (limit 3 > 2) swaps 3 -> 2 (-10),
       frame 0 (limit 1 <= 2) stops the walk */
    if (limit_sum(&bm, 2) != 1000 + 20 - 10) return fail("limit 2");
    /* limit 4: the top frame +40, frame 1 (3 <= 4) stops the walk */
    if (limit_sum(&bm, 4) != 1000 + 40) return fail("limit 4");
    /* limit 0: the top frame is unchanged, frame 1 (3 > 0) swaps 3 -> 0 (-30), frame 0 (1 > 0) swaps 1 -> 0 (-10) */
    if (limit_sum(&bm, 0) != 1000 - 30 - 10) return fail("limit 0");
